// --- Feature preprocessing ---------------------------------------------------
const spotProb = record.spotProbs[0];                 // Base market-implied prob
const sentiment = record.newsSentiment;               // 0.0 – 1.0
const whaleFlow = Math.min(record.whaleFlow, 100);   // cap at 100 USDC
const whaleNorm = whaleFlow / 100;                    // 0.0 – 1.0

// Category bias (empirically‑derived small edge)
const catBiasMap = { crypto: 0.05, politics: -0.02, economics: 0.00 };
const catBias = catBiasMap[record.category] ?? 0;

// --- Alpha construction ------------------------------------------------------
// 1️⃣ Adjust the spot probability toward the news sentiment.
//    Strong positive sentiment pushes the probability up, negative pushes down.
const sentimentAdj = (sentiment - 0.5) * 0.2; // sentiment weight = 20 %
let probAdj = spotProb * (1 + sentimentAdj);

// 2️⃣ Add an institutional‑flow signal. Large USDC inflow from whales is taken as a
//    bullish indicator (scaled by 0.1 to keep the signal modest).
probAdj += whaleNorm * 0.1;

// 3️⃣ Apply the category bias.
probAdj += catBias;

// 4️⃣ Clamp to a valid probability range.
const estimatedProb = Math.max(0, Math.min(1, probAdj));

// --- Confidence estimation ---------------------------------------------------
// Base confidence rises with distance from the indecisive 0.5 line.
let confidence = 0.5 + 0.45 * Math.abs(estimatedProb - 0.5); // 0.5 → 0.95

// Refine confidence using the covariance matrix.
// Assume covMatrix is a square matrix aligned with our three signals (spot, sentiment, flow).
// Higher diagonal variance → lower confidence.
if (Array.isArray(covMatrix) && covMatrix.length) {
    const diag = covMatrix.map((row, i) => row[i] ?? 0);
    const avgVar = diag.reduce((a, v) => a + v, 0) / diag.length;
    // Scale confidence down proportionally if avg variance > 0.02 (arbitrary threshold)
    const varPenalty = Math.min(0.3, Math.max(0, (avgVar - 0.02) * 5));
    confidence = Math.max(0.5, confidence - varPenalty);
}

// Clamp confidence to the required range.
confidence = Math.max(0.5, Math.min(0.95, confidence));

// --- Voting rule -------------------------------------------------------------
let vote;
if (estimatedProb >= 0.6) {
    vote = 'BUY_YES';
} else if (estimatedProb <= 0.4) {
    vote = 'BUY_NO';
} else {
    vote = 'SKIP';
}

// --- Return result ------------------------------------------------------------
return { vote, confidence, estimatedProb };
