const { spotProbs, newsSentiment, whaleFlow, category } = record;

// 1️⃣ Base market implied probability
let est = spotProbs[0];

// 2️⃣ News sentiment adjustment (±0.1 max)
est += (newsSentiment - 0.5) * 0.2;

// 3️⃣ Whale USDC flow adjustment – diminishing returns, max ~+0.10
est += Math.tanh(whaleFlow / 50) * 0.1;

// 4️⃣ Category bias (empirical)
if (category === 'crypto')       est += 0.05;
else if (category === 'politics') est -= 0.02;
else if (category === 'economics') est += 0.02;

// Clamp to [0,1]
est = Math.max(0, Math.min(1, est));

// 5️⃣ Risk weighting using the first diagonal element of the covariance matrix
// (fallback to a modest variance if matrix missing)
const variance = (covMatrix && covMatrix[0] && covMatrix[0][0]) ?? 0.02;
const riskWeight = Math.exp(-variance * 5); // between ~0.5‑1

// 6️⃣ Confidence scales with (a) risk weighting and (b) distance from 0.5
let confidence = 0.5 + 0.45 * riskWeight * (est > 0.5 ? est : 1 - est);
confidence = Math.max(0.5, Math.min(0.95, confidence));

// 7️⃣ Voting rule
let vote = 'SKIP';
if (confidence > 0.7) {
  vote = est >= 0.5 ? 'BUY_YES' : 'BUY_NO';
}

// 8️⃣ Return the decision packet
return { vote, confidence, estimatedProb: est };
